INSERT INTO feature VALUES('closure-axes','sessions','A closure crosses by its image','open-judgement','implemented','uncommon','mainstream languages','A thunk has no crossing of its own: one a migration returns crosses when every hypothesis it captures and every declaration homed at its world that it names is mobile and open, the image recorded where the thunk is formed. A capture that stays is refused `Immobile.Capture`, or `NotOpen.Capture` under a handle, and a homed declaration `Immobile.Homed` or `NotOpen.Homed`. The image''s three axes are the capture rules: the region by `KeptEscaped`, the grade and access mode by `HeldCaptured`, the world by `Elsewhere`. A thunk reached through a variable or a call carries no image and stays. A thunk it lets cross runs at the caller, forced or applied there, as it runs in place (world-migration).','core-checker core-incremental surface-corpus surface-diagnostics','corpus/model/worlds/closure-axes.gandr corpus/pathological/worlds/closure-axes.gandr corpus/model/worlds/open.gandr corpus/pathological/worlds/open.gandr corpus/pathological/worlds/immobile-crossing.gandr','corpus/model/worlds/closure-axes.gandr',NULL);
